(() => {
  "use strict";
  const $ = id => document.getElementById(id);
  const ASSET = "assets/";
  const STORE = "nobulous-suite-v1";
  const COLORS = ["purple","purple","purple","purple","blue","blue","blue","blue","green","green","green","green","yellow","yellow","yellow","yellow","red"];
  const FACE = {
    purple:["✦","✦","✦","✦","✷",""], blue:["✦","✦","✦","✷","",""],
    green:["✦","✦","✷","","",""], yellow:["✦","✷","","","",""], red:["✦","✦","✦","✦","✦","✷"]
  };
  const BAT_ENCOUNTERS = [
    ["Basic Calibration",2,"No additional effect."],["Fine Manipulation",2,"At least one applied hit must be Yellow."],["Structural Integrity",3,"No additional effect."],["Precision Assembly",3,"No additional effect."],["Performance Trial",3,"No additional effect."],["Load Bearing",3,"At least one applied hit must be Purple."],["Diagnostics",3,"At least one applied hit must be Blue."],["Rapid Response",3,"At least one applied hit must be Green."],["Full Spectrum Test",3,"Applied hits must include at least 3 different colors."],["Limited Workspace",3,"Commit no more than 2 dice initially."],["Resource Constraint",3,"Red cannot be used."],["Independent Work",3,"You cannot borrow a die."],["Prototype Shortage",3,"During your second Strategy phase, commit no additional dice."],["Unreliable Equipment",3,"One committed die cannot be rerolled."],["Color Blind",3,"Before committing, choose one color; it cannot be used."],["Stress Test",4,"No additional effect."],["Exhaustive Testing",4,"Recover 1 fewer die this turn (minimum 0)."],["Nobulous' Deadline",4,"No additional effect."],["Risky Shortcut",4,"You may reduce Target by 1; a borrowed die is then automatically banished."],["What Could Go Wrong?",5,"No additional effect."]
  ];
  const BAT_UPGRADES = [
    ["Serrated Claws",2],["Reinforced Jaw",3],["Capacitor Muscles",3],["Piercing Horn",4],["Spring-Loaded Legs",2],["Prehensile Tail",2],["Tripwire Tendons",3],["Evasive Reflexes",3],["Thickened Hide",2],["Layered Carapace",3],["Chromatic Plating",3],["Reactive Shell",4],["Acute Hearing",2],["Predatory Focus",3],["Rapid Metabolism",2],["Neural Overclock",4]
  ];
  const BAT_SPECIMENS = ["Titanium-Toothed Mole","Voltaic Mantis","Blink Hare","Ghost Gecko","Ironback Beetle","Prismatic Tortoise","Echo Bat","Regenerator Newt"];
  const NAP_TASKS = [
    ["Organize the Specimen Cabinet",2,3,"Y",0],["Prepare the Tissue Samples",3,5,"G",1],["Calibrate the Neural Imager",4,5,"B",1],["Stabilize the Prototype Brain",5,7,"P",2],["Sterilize the Surgical Tools",3,4,"Y",0],["Label the Neural Samples",3,4,"G",0],["Monitor the Growth Vats",3,5,"B",0],["Tune the Cranial Resonator",5,6,"P",0],["Prepare the Transplant Rig",4,5,"G",1],["Align the Memory Probes",4,9,"B",1],["Test the Cerebral Coupler",4,5,"B",1],["Recalibrate the Bone Saw",4,9,"P",1],["Prime the Synaptic Pump",5,9,"P",1],["Map the Council Brain",6,7,"P",1],["Condition the Donor Tissue",3,5,"Y",1],["Verify the Identity Matrix",4,9,"B",2],["Complete the Splice Protocol",5,7,"P",2],["Document the Procedure",3,4,"G",0],["Suture the Donor Incision",4,9,"Y",1],["Decode Nobulous' Lecture Notes",4,5,"G",0],["Update Nobulous' Lab Notes",3,4,"Y",0],["Inventory the Spare Organs",3,4,"G",0],["Clean the Restraint Table",4,5,"B",0],["Reassemble the Automaton Hand",6,8,"P",1],["Dispose of Failed Samples",4,9,"B",1],["Sharpen the Surgical Implements",4,5,"P",0]
  ];
  const NAP_OPPS = ["Take an Unauthorized Break","Raid the Supply Closet","Borrow Better Instruments","Study Nobulous' Notes","Salvage Useful Components","Practice on a Spare Brain"];
  const NAP_SETBACKS = [["Power Failure",6],["Contaminated Workbench",6],["Jammed Centrifuge",7],["Broken Neural Imager",7],["Escaped Specimen",8],["Automaton Malfunction",8]];
  const SCENARIOS = [
    ["The Physician's Greeting","Knowledge","Anatomy",8,"The first NAP card spent also performs Special Recovery."],["An Old Injury","Knowledge","Anatomy",9,"At least 2 Purple or Blue dice must contribute."],["The Chamber Mechanism","Knowledge","Engineering",8,"Success: recover 2 exhausted dice."],["Failed Apparatus","Knowledge","Engineering",10,"Failure: place two cards in Suspicion."],["Order of Precedence","Knowledge","Procedure",9,"Commit at least 3 different colors."],["The Vote","Knowledge","Procedure",8,"Success: recover all exhausted dice of one color."],["A Disputed Citation","Knowledge","Theory",9,"Suspicion does not increase this Target."],["The Long Argument","Knowledge","Theory",10,"Spend at most one NAP card."],["The Ceremonial Seal","Physical","Power",8,"At least one Purple die must contribute."],["An Unwelcome Embrace","Physical","Power",9,"+1 STR for this Scenario."],["The Narrow Stair","Physical","Mobility",8,"Success: next Scenario Target −1."],["A Sudden Fall","Physical","Mobility",10,"Cannot be avoided with an AoS card."],["The Long Session","Physical","Defense",9,"Commit at least 6 dice."],["Tainted Wine","Physical","Defense",10,"Failure must lose 1 Health."],["Across the Chamber","Physical","Senses",8,"Look at the next Scenario before rolling."],["The Darkened Corridor","Physical","Senses",9,"Yellow dice cannot contribute."],["Tracks in the Yard","Cover-Up","Approach",8,"Success: recover one die of each of two colors."],["The Night Watchman's Account","Cover-Up","Approach",9,"A Crit counts as 3 successes."],["An Open Window","Cover-Up","Concealment",8,"At least 3 different colors must contribute."],["Someone Was Seen","Cover-Up","Concealment",10,"If avoided, put it on top instead of bottom."],["Rope Burns","Cover-Up","Restraint",9,"Discard one Research card at random before rolling."],["The Sedative Ledger","Cover-Up","Restraint",9,"Success: recover 3 exhausted dice."],["The Missing Hours","Cover-Up","Extraction",10,"An additional +1 Target per Suspicion."],["A Second Search","Cover-Up","Extraction",8,"Remove one Suspicion, then attempt normally."]
  ];

  const shuffle = a => { a=[...a]; for(let i=a.length-1;i;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];} return a; };
  const freshDice = () => COLORS.map((color,id)=>({id,color,zone:"available",selected:false,face:""}));
  const freshBatRats = () => ["Rummage","Fidget","Whiz","Mottle"].map((n,i)=>({n,hp:[1,1,2,2][i],u:0,side:"front",dice:["purple","blue","green","yellow"].map((color,j)=>({id:`rat-${i}-${j}`,color,zone:"available",selected:false,face:""}))}));
  const fresh = () => ({
    config:{mode:"standalone",tier:"0",finale:"sample"},
    bat:{difficulty:"Standard",encounters:shuffle([...Array(20).keys()]),upgrades:[],current:null,splices:0,round:0,rats:freshBatRats(),activeRat:0,redHolder:0,redZone:"available"},
    nap:{day:1,slot:0,hp:2,str:2,rec:2,credits:0,deck:[],row:[],choice:null,notice:"",dice:freshDice()},
    nrj:{hp:4,str:2,rec:3,attempts:0,suspicion:0,deck:[],current:null,pool:18,eligibleAvoid:3,dice:freshDice(),nextDiscount:0}
  });
  let state=fresh();
  try{const s=JSON.parse(localStorage.getItem(STORE));if(s)state={...fresh(),...s,config:{...fresh().config,...s.config}};}catch(_){ }
  if(!state.bat.rats?.every(r=>Array.isArray(r.dice))){const migrated=freshBatRats();(state.bat.rats||[]).forEach((r,i)=>Object.assign(migrated[i]||{},r));state.bat.rats=migrated;}
  if(state.bat.activeRat===undefined)state.bat.activeRat=0;if(state.bat.redHolder===undefined)state.bat.redHolder=0;if(!state.bat.redZone)state.bat.redZone="available";if(state.nap.notice===undefined)state.nap.notice="";
  const save=()=>localStorage.setItem(STORE,JSON.stringify(state));

  function setSprite(el,file,index,cols,rows){const col=index%cols,row=Math.floor(index/cols);el.classList.remove("placeholder-card");el.innerHTML="";el.style.backgroundImage=`url('${ASSET}${file}')`;el.style.backgroundSize=`${cols*100}% ${rows*100}%`;el.style.backgroundPosition=`${cols===1?0:col/(cols-1)*100}% ${rows===1?0:row/(rows-1)*100}%`;}
  function clearSprite(el,text){el.removeAttribute("style");el.classList.add("placeholder-card");el.innerHTML=`<span>${text}</span>`;}
  function stat(label,value){return `<div class="suite-stat"><span>${label}</span><strong>${value}</strong></div>`;}
  function overlayText(){return state.config.mode==="standalone"?"Standalone · no campaign cards mixed in":`NRJ Tier ${["","I · Agenda","II · Contamination","III · Exploitation"][Number(state.config.tier)]||"None"} active · use the matching module deck from the rules.`;}

  function showScreen(name){document.querySelectorAll(".game-screen").forEach(x=>x.classList.toggle("hidden",x.id!==`screen-${name}`));$("gameNav").value=name;document.querySelectorAll(".aos-only").forEach(x=>x.classList.toggle("hidden",name!=="aos"));if(name==="bat")renderBAT();if(name==="nap")renderNAP();if(name==="nrj")renderNRJ();window.scrollTo({top:0,behavior:"smooth"});}

  function buildBAT(){const specimens={Easy:4,Standard:5,Hard:6,Brutal:7,Nobulous:8}[state.bat.difficulty];state.bat.encounters=shuffle([...Array(20).keys()]);state.bat.upgrades=shuffle([...Array(16).keys()].map(i=>({type:"u",i})).concat(shuffle([...Array(8).keys()]).slice(0,specimens).map(i=>({type:"s",i}))));state.bat.current=null;state.bat.splices=0;state.bat.round=0;state.bat.rats=freshBatRats();state.bat.activeRat=0;state.bat.redHolder=Math.floor(Math.random()*4);state.bat.redZone="available";state.bat.redSelected=false;state.bat.redFace="";save();renderBAT();}
  function drawBAT(){if(!state.bat.upgrades.length)buildBAT();if(!state.bat.encounters.length||state.bat.upgrades.length<2)return;state.bat.current={e:state.bat.encounters.pop(),a:state.bat.upgrades.pop(),b:state.bat.upgrades.pop()};save();renderBAT();}
  function upgradeName(c){return c.type==="s"?BAT_SPECIMENS[c.i]:BAT_UPGRADES[c.i][0];}
  function upgradeValue(c){return c.type==="s"?5:BAT_UPGRADES[c.i][1];}
  function resolveBAT(keep){const c=state.bat.current;if(!c)return;if(keep){state.bat.rats[state.bat.activeRat].u=Math.min(3,state.bat.rats[state.bat.activeRat].u+1);}else state.bat.splices++;state.bat.round++;state.bat.current=null;save();renderBAT();}
  function ratDieButton(d,ratIndex){return `<button class="rat-die ${d.color} ${d.zone} ${d.selected?"selected":""}" data-bat-die="${d.id}" data-rat="${ratIndex}" title="${d.zone==="exhausted"?"Tap to recover":"Tap to select"}">${d.face||""}</button>`;}
  function renderBATRats(){const b=state.bat,host=$("batRats");host.innerHTML="";b.rats.forEach((r,i)=>{const available=r.dice.filter(d=>d.zone==="available").map(d=>ratDieButton(d,i)).join("");const exhausted=r.dice.filter(d=>d.zone==="exhausted").map(d=>ratDieButton(d,i)).join("");const banished=r.dice.filter(d=>d.zone==="banished").length;const redAvailable=b.redHolder===i&&b.redZone==="available"?`<button class="rat-die red ${b.redSelected?"selected":""}" data-bat-red="1" title="Communal Red die">${b.redFace||""}</button>`:"";const redAside=b.redHolder===i&&b.redZone==="setaside"?`<div class="red-set-aside">Red is set aside · move it to a non-active Rat for the next Encounter</div>`:"";const box=document.createElement("article");box.className=`bat-rat ${b.activeRat===i?"active":""}`;box.dataset.batActive=i;box.innerHTML=`<div class="bat-rat-head"><h3>${r.n}</h3><button data-rat-side="${i}">Side ${r.side==="front"?"A":"B"}</button></div><div class="suite-card landscape bat-rat-card"></div><div class="bat-dice-summary"><span>${r.hp} HP</span><span>${r.u} Upgrades</span><span>${banished} Banished</span></div><div class="rat-dice-zones"><div class="rat-dice-zone"><h4>Available</h4><div class="rat-dice-row">${available}${redAvailable}</div></div><div class="rat-dice-zone"><h4>Exhausted</h4><div class="rat-dice-row">${exhausted}</div></div></div>${redAside}<div class="bat-rat-actions"><button data-move-red="${i}">Move Red here</button><button data-rat-hp="${i}" data-delta="-1">− HP</button><button data-rat-hp="${i}" data-delta="1">+ HP</button></div>`;setSprite(box.querySelector(".bat-rat-card"),r.side==="front"?"BAT_Rats_TTS.png":"BAT_Rats_TTS_back.png",i,4,1);host.appendChild(box);});}
  function renderBATDice(){const b=state.bat,selected=b.rats.flatMap(r=>r.dice).filter(d=>d.selected).length+(b.redSelected?1:0);$("batRoller").innerHTML=`<div class="roller-head"><div><p class="kicker">Active commitment</p><h2>${b.rats[b.activeRat].n} · ${selected} selected</h2></div><div class="compact-actions"><button id="batRollSelected" class="primary">Roll selected</button><button id="batBanishSelected">Banish selected</button><button id="batReadyAll">Ready all personal dice</button></div></div><div class="roll-result" id="batRollResult">Tap available dice in the Rat panels. Borrow at most one die from another Rat.</div>`;}
  function rollBAT(){const b=state.bat,rolled=b.rats.flatMap(r=>r.dice).filter(d=>d.selected&&d.zone==="available");let successes=0,crits=0,redRolled=0;rolled.forEach(d=>{d.face=FACE[d.color][Math.floor(Math.random()*6)];successes+=d.face==="✷"?2:d.face==="✦"?1:0;crits+=d.face==="✷"?1:0;d.zone="exhausted";d.selected=false;});if(b.redSelected&&b.redZone==="available"){b.redFace=FACE.red[Math.floor(Math.random()*6)];successes+=b.redFace==="✷"?2:1;crits+=b.redFace==="✷"?1:0;redRolled=1;b.redZone="setaside";b.redSelected=false;}save();renderBATRats();renderBATDice();$("batRollResult").textContent=`${successes} successes from ${rolled.length+redRolled} dice (${crits} Crits).`;}
  function renderBAT(){const b=state.bat;$("batOverlay").textContent=overlayText();$("batDifficulty").value=b.difficulty;$("batRat").selectedIndex=b.activeRat;$("batStats").innerHTML=stat("Splices",`${b.splices} / 5`)+stat("Encounters",b.round)+stat("Deck",b.encounters.length)+stat("Red",b.redZone==="setaside"?"Set aside":b.rats[b.redHolder].n);renderBATRats();if(!b.current){clearSprite($("batEncounter"),b.splices>=5?"Tyrant awake — begin battle":"Reveal an Encounter");clearSprite($("batUpgradeA"),"Upgrade A");clearSprite($("batUpgradeB"),"Upgrade B");$("batEncounterText").textContent="";}else{const e=BAT_ENCOUNTERS[b.current.e],spec=(b.current.a.type==="s"||b.current.b.type==="s")?1:0;setSprite($("batEncounter"),"BAT_Encounters_TTS.png",b.current.e,10,2);setSprite($("batUpgradeA"),b.current.a.type==="s"?"BAT_Specimens_TTS.png":"BAT_Upgrades_TTS.png",b.current.a.i,b.current.a.type==="s"?8:10,b.current.a.type==="s"?1:2);setSprite($("batUpgradeB"),b.current.b.type==="s"?"BAT_Specimens_TTS.png":"BAT_Upgrades_TTS.png",b.current.b.i,b.current.b.type==="s"?8:10,b.current.b.type==="s"?1:2);$("batEncounterText").innerHTML=`<strong>${e[0]} · Target ${e[1]+spec}</strong><br>${e[2]}${spec?"<br><em>Specimen revealed: +1 Target.</em>":""}`;}renderBATDice();}

  function napCard(type,i){if(type==="t")return {name:NAP_TASKS[i][0],file:"NAP_Tasks_TTS.png",i,cols:10,rows:3,target:NAP_TASKS[i][1],demand:NAP_TASKS[i][2],dot:NAP_TASKS[i][3],skulls:NAP_TASKS[i][4]};if(type==="o")return{name:NAP_OPPS[i],file:"NAP_Opportunities_TTS.png",i,cols:6,rows:1,target:i<2?4:5,demand:i<2?4:5,dot:"Y",skulls:0};return{name:NAP_SETBACKS[i][0],file:"NAP_Setbacks_TTS.png",i,cols:6,rows:1,target:NAP_SETBACKS[i][1],demand:NAP_SETBACKS[i][1],dot:"—",skulls:0};}
  function buildNAP(){const setback=shuffle([...Array(6).keys()]).slice(0,3).map(i=>({type:"s",i}));state.nap={day:1,slot:0,hp:2,str:2,rec:2,credits:0,deck:shuffle([...Array(26).keys()].map(i=>({type:"t",i})).concat([...Array(6).keys()].map(i=>({type:"o",i})),setback)),row:[],choice:null,notice:"",dice:freshDice()};save();renderNAP();}
  function revealNAP(){if(state.nap.row.length>=4||state.nap.deck.length<2)return;state.nap.choice=[state.nap.deck.pop(),state.nap.deck.pop()];$("napChoice").classList.remove("hidden");renderNAP();}
  function chooseNAP(which){let c=state.nap.choice[which];if(state.nap.choice.some(x=>x.type==="s"))c=state.nap.choice.find(x=>x.type==="s");const primary={...c,demandSide:false,progress:0,id:Date.now(),source:"primary"};state.nap.row.push(primary);const skulls=napCard(c.type,c.i).skulls||0,added=[];let blocked=false;for(let k=0;k<skulls;k++){if(state.nap.row.length<4&&state.nap.deck.length){const extra=state.nap.deck.pop();state.nap.row.push({...extra,demandSide:false,progress:0,id:Date.now()+k+1,source:"skull"});added.push(napCard(extra.type,extra.i).name);}else if(!blocked){primary.demandSide=true;blocked=true;}}state.nap.notice=skulls?`${skulls} Skull${skulls===1?"":"s"}: ${added.length?`added ${added.join(" and ")}`:"no card added"}${blocked?"; the row was full, so the Primary flipped to Demand.":". Added cards do not resolve their own Skulls."}`:"";state.nap.choice=null;save();renderNAP();}
  function advanceNAP(){state.nap.row.forEach(a=>a.demandSide=true);state.nap.notice="";state.nap.slot++;if(state.nap.slot>2){state.nap.slot=0;state.nap.day++;state.nap.deck.pop();}save();renderNAP();}
  function renderNAPSlots(){const names=["Morning","Afternoon","Evening"],host=$("napTimeSlots");host.innerHTML="";names.forEach((name,i)=>{const box=document.createElement("article");box.className=`nap-slot ${state.nap.slot===i?"active":""}`;box.innerHTML=`<div class="nap-slot-label"><strong>${name}</strong><span>${state.nap.slot===i?"Active now":"Day "+state.nap.day}</span></div><div class="suite-card landscape"></div>`;setSprite(box.querySelector(".suite-card"),"NAP_SlotsFINF_TTS.png",i,4,1);host.appendChild(box);});}
  function renderNAP(){const n=state.nap;$("napOverlay").textContent=overlayText();$("napStats").innerHTML=stat("Day",n.day)+stat("Time",["Morning","Afternoon","Evening"][n.slot])+stat("HP",n.hp)+stat("STR",n.str)+stat("REC",n.rec)+stat("Credits",`${n.credits} / 6`)+stat("Deck",n.deck.length);renderNAPSlots();$("napNotice").textContent=n.notice||"";$("napNotice").classList.toggle("hidden",!n.notice);$("napChoice").classList.toggle("hidden",!n.choice);if(n.choice)n.choice.forEach((x,i)=>{const c=napCard(x.type,x.i);setSprite($(i?"napChoiceB":"napChoiceA"),c.file,c.i,c.cols,c.rows);});$("napRow").innerHTML=n.row.length?"":"<p class='hint'>Reveal two Assignments and choose the Primary. Setbacks are mandatory.</p>";n.row.forEach(a=>{const c=napCard(a.type,a.i),box=document.createElement("article");box.className="assignment";box.innerHTML=`<div class="suite-card landscape"></div><strong>${c.name}</strong><span>Target ${a.demandSide?c.demand:c.target} · stored ${a.progress}</span><span>${c.skulls?`<span class="skull-badge">☠ ${c.skulls}</span> · `:""}${a.source==="skull"?"Added by Skull · its Skulls ignored":a.source==="primary"?"Primary":"Carried assignment"}</span><div class="assignment-actions"><button data-progress="${a.id}">Store +1</button><button data-complete="${a.id}" class="primary">Complete</button></div>`;setSprite(box.querySelector(".suite-card"),c.file,c.i,c.cols,c.rows);$("napRow").appendChild(box);});renderRoller("nap");}

  function buildNRJ(){const byDomain=["Knowledge","Physical","Cover-Up"].flatMap(d=>shuffle(SCENARIOS.map((x,i)=>x[1]===d?i:null).filter(i=>i!==null)).slice(0,4));state.nrj={hp:4,str:2,rec:3,attempts:0,suspicion:0,deck:shuffle(byDomain),current:null,pool:18,eligibleAvoid:3,dice:freshDice(),nextDiscount:0};save();renderNRJ();}
  function drawNRJ(){if(state.nrj.current||state.nrj.attempts>=9)return;if(!state.nrj.deck.length)buildNRJ();state.nrj.current=state.nrj.deck.pop();save();renderNRJ();}
  function nrjTarget(){if(state.nrj.current===null)return null;const s=SCENARIOS[state.nrj.current],ignore=s[0]==="A Disputed Citation",extra=s[0]==="The Missing Hours"?state.nrj.suspicion:0;const reduction=Number($("nrjNapMatch").value||0)*2+Number($("nrjBatMatch").value||0)*3+Number($("nrjSpecimen").value||0)*5+Number($("nrjAosStable").value||0)*4+Number($("nrjAosHot").value||0)*2+Number($("nrjWrong").value||0)*2;return Math.max(0,s[3]+(ignore?0:state.nrj.suspicion)+extra-state.nrj.nextDiscount-reduction);}
  function clearNRJInputs(){["nrjNapMatch","nrjBatMatch","nrjSpecimen","nrjAosStable","nrjAosHot","nrjWrong"].forEach(id=>$(id).value=0);}
  function resolveNRJ(success,choice="hp"){if(state.nrj.current===null)return;const s=SCENARIOS[state.nrj.current];const spent=["nrjNapMatch","nrjBatMatch","nrjSpecimen","nrjAosStable","nrjAosHot","nrjWrong"].reduce((n,id)=>n+Number($(id).value||0),0);if(spent>state.nrj.pool)return;state.nrj.pool-=spent;if(!success){state.nrj.suspicion+=s[0]==="Failed Apparatus"?2:1;if(choice==="hp"||s[0]==="Tainted Wine")state.nrj.hp--;else{let n=2;state.nrj.dice.filter(d=>d.zone==="available").forEach(d=>{if(n){d.zone="banished";n--;}});if(n)state.nrj.hp--;}}state.nrj.nextDiscount=success&&s[0]==="The Narrow Stair"?1:0;state.nrj.attempts++;state.nrj.current=null;clearNRJInputs();save();renderNRJ();}
  function renderNRJ(){const n=state.nrj;$("nrjOverlay").textContent=`${$("nrjPoolMode")?.value==="campaign"?"Campaign":"Standalone sample"} · survive 9 attempts`;$("nrjStats").innerHTML=stat("HP",n.hp)+stat("STR",n.str)+stat("REC",n.rec)+stat("Attempts",`${n.attempts} / 9`)+stat("Suspicion",n.suspicion)+stat("Research",n.pool)+stat("Avoid cards",n.eligibleAvoid);if(n.current===null){clearSprite($("nrjScenario"),n.attempts>=9?(n.hp>0?"Finale survived":"The Imposter was exposed"):"Reveal a Scenario");$("nrjScenarioText").textContent="";}else{const s=SCENARIOS[n.current];setSprite($("nrjScenario"),"NRJ_ImposterScenarios_TTS.png",n.current,10,3);$("nrjScenarioText").innerHTML=`<strong>${s[0]} · ${s[1]} / ${s[2]}</strong><br>Printed Target ${s[3]} · ${s[4]}`;}updateNRJTarget();renderRoller("nrj");}
  function updateNRJTarget(){const t=nrjTarget();$("nrjTarget").textContent=t===null?"—":t;}

  function renderRoller(game){const host=$(`${game}Roller`),dice=state[game].dice;host.innerHTML=`<div class="roller-head"><div><p class="kicker">20 Strong dice</p><h2>Tap available dice to commit</h2></div><div class="compact-actions"><button data-roll="${game}" class="primary">Roll selected</button><button data-recover="${game}">Recover up to REC</button><button data-ready="${game}">Ready all</button></div></div><div class="roller-dice"></div><div class="roll-result"></div>`;const row=host.querySelector(".roller-dice");dice.forEach(d=>{const b=document.createElement("button");b.className=`roll-die ${d.color} ${d.zone} ${d.selected?"selected":""}`;b.textContent=d.face||"";b.title=`${d.color} · ${d.zone}`;b.onclick=()=>{if(d.zone!=="available")return;d.selected=!d.selected;save();renderRoller(game);};row.appendChild(b);});}
  function rollSelected(game){const dice=state[game].dice.filter(d=>d.zone==="available"&&d.selected);let successes=0;dice.forEach(d=>{d.face=FACE[d.color][Math.floor(Math.random()*6)];successes+=d.face==="✷"?2:d.face==="✦"?1:0;d.zone="exhausted";d.selected=false;});save();renderRoller(game);$(`${game}Roller`).querySelector(".roll-result").textContent=`${successes} successes from ${dice.length} dice (${dice.filter(d=>d.face==="✷").length} Crits).`;}
  function recover(game){let n=state[game].rec||2;state[game].dice.filter(d=>d.zone==="exhausted").forEach(d=>{if(n){d.zone="available";d.face="";n--;}});save();renderRoller(game);}
  function ready(game){state[game].dice.forEach(d=>{if(d.zone!=="banished")d.zone="available";d.face="";d.selected=false;});save();renderRoller(game);}

  document.addEventListener("click",e=>{
    const open=e.target.closest("[data-open-game]");if(open)showScreen(open.dataset.openGame);
    const ng=e.target.closest("[data-new-game]");if(ng){if(ng.dataset.newGame==="bat")buildBAT();if(ng.dataset.newGame==="nap")buildNAP();if(ng.dataset.newGame==="nrj")buildNRJ();}
    const pc=e.target.closest("[data-progress]");if(pc){const a=state.nap.row.find(x=>x.id==pc.dataset.progress);if(a)a.progress++;save();renderNAP();}
    const cc=e.target.closest("[data-complete]");if(cc){const i=state.nap.row.findIndex(x=>x.id==cc.dataset.complete);if(i>=0){if(state.nap.row[i].type==="t")state.nap.credits++;state.nap.row.splice(i,1);}save();renderNAP();}
    const roll=e.target.closest("[data-roll]");if(roll)rollSelected(roll.dataset.roll);
    const rec=e.target.closest("[data-recover]");if(rec)recover(rec.dataset.recover);
    const readyBtn=e.target.closest("[data-ready]");if(readyBtn)ready(readyBtn.dataset.ready);
    const ratPanel=e.target.closest(".bat-rat");if(ratPanel&&!e.target.closest("button")){state.bat.activeRat=Number(ratPanel.dataset.batActive);save();renderBAT();}
    const ratDie=e.target.closest("[data-bat-die]");if(ratDie){const d=state.bat.rats.flatMap(r=>r.dice).find(x=>x.id===ratDie.dataset.batDie);if(d){if(d.zone==="exhausted"){d.zone="available";d.face="";d.selected=false;}else if(d.zone==="available")d.selected=!d.selected;save();renderBATRats();renderBATDice();}}
    const redDie=e.target.closest("[data-bat-red]");if(redDie){state.bat.redSelected=!state.bat.redSelected;save();renderBATRats();renderBATDice();}
    const redMove=e.target.closest("[data-move-red]");if(redMove){state.bat.redHolder=Number(redMove.dataset.moveRed);state.bat.redZone="available";state.bat.redSelected=false;state.bat.redFace="";save();renderBAT();}
    const side=e.target.closest("[data-rat-side]");if(side){const r=state.bat.rats[Number(side.dataset.ratSide)];r.side=r.side==="front"?"back":"front";save();renderBAT();}
    const hp=e.target.closest("[data-rat-hp]");if(hp){const r=state.bat.rats[Number(hp.dataset.ratHp)];r.hp=Math.max(0,r.hp+Number(hp.dataset.delta));save();renderBAT();}
    if(e.target.closest("#batRollSelected"))rollBAT();
    if(e.target.closest("#batBanishSelected")){state.bat.rats.flatMap(r=>r.dice).filter(d=>d.selected).forEach(d=>{d.zone="banished";d.selected=false;d.face="";});save();renderBAT();}
    if(e.target.closest("#batReadyAll")){state.bat.rats.flatMap(r=>r.dice).forEach(d=>{if(d.zone!=="banished")d.zone="available";d.selected=false;d.face="";});save();renderBAT();}
  });
  $("homeBtn").onclick=()=>showScreen("home");$("gameNav").onchange=e=>showScreen(e.target.value);
  ["campaignMode","nrjTier","finaleMode"].forEach(id=>{const key={campaignMode:"mode",nrjTier:"tier",finaleMode:"finale"}[id];$(id).value=state.config[key];$(id).onchange=e=>{state.config[key]=e.target.value;save();};});
  $("batDifficulty").onchange=e=>{state.bat.difficulty=e.target.value;buildBAT();};$("batRat").onchange=e=>{state.bat.activeRat=e.target.selectedIndex;save();renderBAT();};$("batDraw").onclick=drawBAT;$("batSuccessA").onclick=()=>resolveBAT("a");$("batSuccessB").onclick=()=>resolveBAT("b");$("batFail").onclick=()=>resolveBAT(null);$("batBattle").onclick=()=>{state.bat.splices=Math.max(5,state.bat.splices);save();renderBAT();};
  $("napReveal").onclick=revealNAP;$("napAdvance").onclick=advanceNAP;document.querySelectorAll("[data-nap-choice]").forEach(b=>b.onclick=()=>chooseNAP(Number(b.dataset.napChoice)));
  $("nrjBuildPool").onclick=buildNRJ;$("nrjDraw").onclick=drawNRJ;$("nrjAvoid").onclick=()=>{if(state.nrj.current===null||state.nrj.eligibleAvoid<1)return;const s=SCENARIOS[state.nrj.current];if(s[0]==="A Sudden Fall")return;state.nrj.eligibleAvoid--;state.nrj.pool=Math.max(0,state.nrj.pool-1);if(s[0]==="Someone Was Seen")state.nrj.deck.push(state.nrj.current);else state.nrj.deck.unshift(state.nrj.current);state.nrj.current=null;save();renderNRJ();};$("nrjSuccess").onclick=()=>resolveNRJ(true);$("nrjFailHp").onclick=()=>resolveNRJ(false,"hp");$("nrjFailDice").onclick=()=>resolveNRJ(false,"dice");["nrjNapMatch","nrjBatMatch","nrjSpecimen","nrjAosStable","nrjAosHot","nrjWrong"].forEach(id=>$(id).oninput=updateNRJTarget);
  if(!state.bat.upgrades.length)buildBAT();if(!state.nap.deck.length)buildNAP();if(!state.nrj.deck.length)buildNRJ();showScreen("home");
})();
